// Alle Text-Teile der KI-Antwort lesen: neuere Modelle liefern davor einen (leeren) thinking-Block (Stefan 18.10.2026)
const kiTeile = $input.item.json.content;
const raw = (Array.isArray(kiTeile) ? kiTeile : []).filter(b => b && b.type === 'text' && b.text).map(b => String(b.text)).join('\n');
let parsed;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parsed = { kategorie_key: 'keine', konfidenz: 0, begruendung: 'Parse-Fehler: ' + raw, zeitkritisch: false };
}

const regel = $('4_5b_regeln_laden').item.json;
// Kooperationsanfrage nur mit gebuchtem Paket Talents, sonst wie bisher keine (Stefan 18.10.2026, Vertrag Migration 49)
const erlaubt = ['kunde', 'geschaeft', 'spam', 'system_report', 'keine'].concat(regel.talents_an === true ? ['kooperation'] : []);
if (!erlaubt.includes(parsed.kategorie_key)) parsed.kategorie_key = 'keine';

// Konto-Warnung (Schutzregel): kein Entwurfsangebot, nicht fuer Entwurf auf Zuruf speichern (Stefan 17.10.2026)
let kontoWarnung = false;
if (regel.regel_kategorie) {
  // Gelernte Absender-Regel hat immer Vorrang vor der KI-Einschaetzung
  parsed.begruendung = 'Absender-Regel ' + regel.regel_muster + ' (KI: ' + parsed.kategorie_key + ' – ' + (parsed.begruendung || '') + ')';
  parsed.kategorie_key = regel.regel_kategorie;
  parsed.konfidenz = 1;
  // Absender-Regel kooperation ohne Paket Talents: keine (Stefan 18.10.2026)
  if (parsed.kategorie_key === 'kooperation' && regel.talents_an !== true) parsed.kategorie_key = 'keine';
} else {
  // Schutzregeln nach der KI-Einordnung, nur ohne Absender-Regel: die Absender-Regel gewinnt immer (Stefan 17.10.2026)
  const betreff = String($('4_5_eingang_zusammenfuehren').item.json.subject || '');
  const WARNUNG = /credit balance|api access|action needed|action required|turned off|suspended|payment failed|zahlung fehlgeschlagen|konto gesperrt|guthaben/i;
  const GELD = /rechnung|invoice|receipt|quittung|beleg|zahlung|payment|kontoauszug|abrechnung|gutschrift|mahnung|steuer|finanzamt|elster|\bust\b|\bvat\b|bank|lastschrift|\bsepa\b|refund|erstattung/i;
  let schutz = false;
  if (parsed.kategorie_key !== 'kunde' && WARNUNG.test(betreff)) {
    // Warnung eines Dienstes zu Konto, Guthaben oder Zugang: nie spam/system_report, sondern geschaeft und zeitkritisch (Stefan 17.10.2026)
    parsed.begruendung = 'Schutzregel: Warnung zu Konto oder Zugang (KI: ' + parsed.kategorie_key + ' – ' + (parsed.begruendung || '') + ')';
    parsed.kategorie_key = 'geschaeft';
    parsed.zeitkritisch = true;
    // Dienste-Warnungen brauchen keine Antwort, Phishing bekommt kein Antwortangebot (Stefan 17.10.2026)
    parsed.antwort_erwartet = false;
    kontoWarnung = true;
    schutz = true;
  } else if (parsed.kategorie_key === 'kooperation' && GELD.test(betreff)) {
    // Kooperationsanfrage mit Geld-Betreff (Rechnung, Zahlung ...): wie bisher geschaeft, bleibt im Posteingang (Stefan 18.10.2026)
    parsed.begruendung = 'Schutzregel: sieht nach Rechnung/Zahlung/Steuer aus (KI: kooperation – ' + (parsed.begruendung || '') + ')';
    parsed.kategorie_key = 'geschaeft';
    schutz = true;
  } else if (parsed.kategorie_key === 'system_report' && GELD.test(betreff)) {
    // Sieht nach Rechnung/Zahlung/Bank/Steuer aus: bleibt im Posteingang (Stefan 17.10.2026)
    parsed.begruendung = 'Schutzregel: sieht nach Rechnung/Zahlung/Steuer aus, nicht verschoben (KI: system_report – ' + (parsed.begruendung || '') + ')';
    parsed.kategorie_key = 'keine';
    schutz = true;
  }

  // Verschieben nur bei hoher Sicherheit
  const SCHWELLE = 0.8;
  if (['spam', 'system_report'].includes(parsed.kategorie_key) && !(parsed.konfidenz >= SCHWELLE)) {
    parsed.begruendung = 'Unter Schwelle (' + parsed.kategorie_key + ', ' + parsed.konfidenz + '): ' + (parsed.begruendung || '');
    parsed.kategorie_key = 'keine';
  }
  // Schutzregel-Ergebnis nicht durch die Schwelle zuruecksetzen (Stefan 17.10.2026)
  // kooperation mit derselben Mindest-Sicherheit wie kunde und geschaeft (Stefan 18.10.2026)
  if (!schutz && ['kunde', 'geschaeft', 'kooperation'].includes(parsed.kategorie_key) && !(parsed.konfidenz >= 0.6)) {
    parsed.kategorie_key = 'keine';
  }
}

return {
  json: {
    ...$('4_5_eingang_zusammenfuehren').item.json,
    kategorieKey: parsed.kategorie_key,
    konfidenz: parsed.konfidenz,
    begruendung: parsed.begruendung,
    zeitkritisch: parsed.zeitkritisch === true,
    antwortErwartet: parsed.antwort_erwartet === true && !['spam', 'system_report'].includes(parsed.kategorie_key),
    kontoWarnung: kontoWarnung
  }
};

// Gespeicherte Mail-Daten wieder in die Form bringen, die die Einordnung erwartet
const d = $json.daten || {};
return { json: (typeof d === 'string' ? JSON.parse(d) : d) };

// Anhänge von Talents (Stefan 18.10.2026, Vertrag Migration 47 §6, Entscheidung Hauptagent): nur wenn das Paket Talents gebucht ist und nur Bilder
// (PNG, JPG, WEBP) oder PDF. Kostenbremse: Bilder immer, PDF nur, wenn Betreff oder Text nach Statistik klingt (sonst sind es meist Rechnungen).
// Höchstens 5 Anhänge je Mail. Ob der Absender eine hinterlegte Talent-E-Mail ist, prüft danach die Datenbank (talents_manuell_absender).
// Ally antwortet dem Talent nicht und verschiebt nichts; die Mail wird wie bisher eingeordnet.
// Zugehöriges Eingangs-Item (gepaart, sonst gleiche Stelle) (Stefan 18.10.2026)
const passend = (k, i) => { try { return $(k).itemMatching(i); } catch (e) { return $(k).all()[i]; } };
const BILD = ['image/png', 'image/jpeg', 'image/webp'];
const ENDUNG = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp', pdf: 'application/pdf' };
const WOERTER = /statistik|insights|zahlen|reichweite|analytics|screenshot|auswertung/i;
const out = [];
$input.all().forEach((it, i) => {
  const m = passend('4_5_eingang_zusammenfuehren', i);
  const r = passend('4_5b_regeln_laden', i).json || {};
  if (!m || r.talents_an !== true) return;
  const j = m.json || {}, bin = m.binary || {};
  const absender = String((j.from && j.from.value && j.from.value[0] && j.from.value[0].address) || '').trim().toLowerCase();
  if (!absender) return;
  const statistik = WOERTER.test(String(j.subject || '')) || WOERTER.test(String(j.text || '').slice(0, 5000));
  const binaer = {}, namen = [];
  for (const k of Object.keys(bin)) {
    const b = bin[k] || {};
    let mime = String(b.mimeType || '').toLowerCase().split(';')[0].trim();
    if (mime === 'image/jpg') mime = 'image/jpeg';
    if (!mime || mime === 'application/octet-stream') mime = ENDUNG[String(b.fileExtension || String(b.fileName || '').split('.').pop() || '').toLowerCase()] || mime;
    const passt = BILD.includes(mime) || (mime === 'application/pdf' && statistik);
    if (!passt || namen.length >= 5) continue;
    const n = 'a' + namen.length;
    binaer[n] = Object.assign({}, b, { mimeType: mime });
    namen.push({ feld: n, name: String(b.fileName || ('anhang_' + namen.length)).slice(0, 120) });
  }
  if (!namen.length) return;
  const d = j.date ? new Date(j.date) : null;
  out.push({ json: { absender, betreff: String(j.subject || '').slice(0, 200), postfach: String(j.postfach || ''),
    mail_datum: d && !isNaN(d) ? d.toISOString().slice(0, 10) : '', anhaenge: namen }, binary: binaer, pairedItem: { item: i } });
});
return out;

// Je Anhang ein Aufruf von "TALENTS Zahlen auslesen" (Stefan 18.10.2026, Vertrag Migration 47 §6): nur wenn der Absender ein aktives Talent ist.
// Felder laut Vertrag: quelle mail, absender, mail_datum, datei_name, nutzer leer; Datei im Binärfeld "datei". Die Datenbank bestimmt das Talent
// über den Absender und begrenzt auf 20 Dateien je Talent und Tag.
// Zugehöriges Eingangs-Item (gepaart, sonst gleiche Stelle) (Stefan 18.10.2026)
const passend = (k, i) => { try { return $(k).itemMatching(i); } catch (e) { return $(k).all()[i]; } };
const out = [];
$input.all().forEach((it, i) => {
  const r = (it.json || {}).r || {};
  if (r.ok !== true || !(Number(r.talent_id) > 0)) return;
  const q = passend('4_40_talent_anhaenge_finden', i);
  if (!q) return;
  for (const a of q.json.anhaenge || []) {
    const b = (q.binary || {})[a.feld];
    if (!b) continue;
    out.push({ json: { quelle: 'mail', absender: q.json.absender, mail_datum: q.json.mail_datum, datei_name: a.name, nutzer: '',
      _talent_id: Number(r.talent_id), _anzeigename: String(r.anzeigename || ''), _betreff: q.json.betreff, _postfach: q.json.postfach },
      binary: { datei: b }, pairedItem: { item: i } });
  }
});
return out;

// Hinweis an die zuständigen Personen (Stefan 18.10.2026, Entscheidung Hauptagent zu Vertrag Migration 47 §6): je Talent und Mail eine Nachricht
// mit dem Ergebnis aus "TALENTS Zahlen auslesen". Gespeichert wird erst nach Bestätigung auf der Seite des Talents. Ally antwortet dem Talent nicht.
// Zugehöriges Eingangs-Item (gepaart, sonst gleiche Stelle) (Stefan 18.10.2026)
const passend = (k, i) => { try { return $(k).itemMatching(i); } catch (e) { return $(k).all()[i]; } };
const ohneEmoji = v => String(v ?? '').replace(/[\p{Extended_Pictographic}\u{FE0F}\u{200D}]/gu, '').trim();
const gruppen = {};
$input.all().forEach((it, i) => {
  const q = passend('4_42_talent_anhaenge_aufteilen', i);
  if (!q) return;
  const e = q.json, r = it.json || {};
  const key = e._talent_id + '|' + e._betreff + '|' + e._postfach;
  const g = gruppen[key] = gruppen[key] || { talent_id: e._talent_id, name: e._anzeigename, betreff: e._betreff, postfach: e._postfach, zeilen: [] };
  const t = r.error ? 'Die Datei ' + e.datei_name + ' konnte nicht ausgelesen werden.' : ohneEmoji(r.text || ('Die Datei ' + e.datei_name + ' wurde nicht ausgelesen.'));
  if (t && !g.zeilen.includes(t)) g.zeilen.push(t);
});
return Object.values(gruppen).filter(g => g.talent_id > 0 && g.zeilen.length).map(g => ({ json: {
  talent_id: g.talent_id, titel: 'Talents: Zahlen per Mail erhalten',
  text: (g.name || 'Ein Talent') + ' hat per Mail' + (g.postfach ? ' an ' + g.postfach : '') + ' Dateien mit Zahlen geschickt'
    + (g.betreff ? ' (Betreff: ' + ohneEmoji(g.betreff) + ')' : '') + '. ' + g.zeilen.join(' ').slice(0, 1500) } }));

// Eine Chat-Nachricht je Hinweis und Empfänger (Stefan 18.10.2026), Layout wie die Talents-Warnungen: Titel fett mit Doppelpunkt, keine Emojis.
// Testläufe (manuell) senden nichts.
// Zugehöriges Eingangs-Item (gepaart, sonst gleiche Stelle) (Stefan 18.10.2026)
const passend = (k, i) => { try { return $(k).itemMatching(i); } catch (e) { return $(k).all()[i]; } };
if (['manual', 'test'].includes($execution.mode)) return [];
const esc = v => String(v ?? '').split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const out = [];
$input.all().forEach((it, i) => {
  const h = passend('4_44_talent_hinweise_bauen', i);
  if (!h) return;
  const titel = h.json.titel + ':', text = h.json.text;
  for (const e of Array.isArray(it.json.empfaenger) ? it.json.empfaenger : []) {
    const roomId = String((e && e.room_id) || '').trim(), userId = String((e && e.user_id) || '').trim();
    if (!roomId && !userId) continue;
    out.push({ json: { user_id: userId, room_id: roomId, text: titel + '\n' + text, html: '<strong>' + esc(titel) + '</strong><br>' + esc(text) } });
  }
});
return out;

