-- Benachrichtigung in der Oberfläche zur Chat-Nachricht (BA10, Stefan 20.10.2026), Art mail_eingang, gleiche Person wie im Chat.
-- Wirft nie einen Fehler; die Chat-Nachricht läuft unverändert und unabhängig davon (eigener Zweig, läuft vor dem Senden).
SELECT ally_benachrichtigung_aus_chat($1::text, 'mail_eingang', NULLIF($2::text, ''), NULL, NULL, 'MAIL 2') AS r;

-- Nach dem Neueinlesen erneut nachschlagen; ort = Stelle der Einordnung in der Oberfläche (persönlich oder gemeinsam)
SELECT e.aktion, e.ziel_ordner, CASE WHEN p.art = 'persoenlich' THEN 'Mein Konto › Meine Postfächer' ELSE 'Organisation › Gemeinsame Postfächer' END AS ort
FROM mail_einordnung_aktion($2::text, $1::text) e LEFT JOIN ally_postfaecher p ON p.adresse = lower(trim($2::text));
